import math
from numbers import Real


def _finite_number(value):
    return isinstance(value, Real) and not isinstance(value, bool) and math.isfinite(value)


def run_weighted_round(server_weights, client_gradients, client_rate, server_rate, clip_norm):
    try:
        weights = list(server_weights)
        clients = list(client_gradients)
    except TypeError as exc:
        raise ValueError("weights and clients must be sequences") from exc

    if any(not _finite_number(value) for value in weights):
        raise ValueError("server weights must be finite numbers")
    if not _finite_number(client_rate) or client_rate < 0:
        raise ValueError("client_rate must be finite and nonnegative")
    if not _finite_number(server_rate) or server_rate < 0:
        raise ValueError("server_rate must be finite and nonnegative")
    if not _finite_number(clip_norm) or clip_norm <= 0:
        raise ValueError("clip_norm must be finite and positive")

    weighted_delta = [0.0] * len(weights)
    total_examples = 0

    for client in clients:
        try:
            gradients = list(client)
        except TypeError as exc:
            raise ValueError("each client must be a sequence") from exc
        local = [float(value) for value in weights]
        for gradient in gradients:
            try:
                vector = list(gradient)
            except TypeError as exc:
                raise ValueError("each gradient must be a sequence") from exc
            if len(vector) != len(weights) or any(not _finite_number(value) for value in vector):
                raise ValueError("invalid gradient vector")
            norm = math.sqrt(sum(float(value) ** 2 for value in vector))
            scale = min(1.0, clip_norm / norm) if norm else 1.0
            for index, value in enumerate(vector):
                local[index] -= client_rate * float(value) * scale
        count = len(gradients)
        if count:
            for index, value in enumerate(local):
                weighted_delta[index] += value - float(weights[index])
            total_examples += count

    if not total_examples:
        return list(weights)
    return [
        float(value) + server_rate * weighted_delta[index] / total_examples
        for index, value in enumerate(weights)
    ]

